<?php declare(strict_types=1);
namespace FMonitor2\PilotHttp;

final class ProductionObjectCardRenderer implements ObjectCardRenderer,CompatibilityObjectCardRenderer
{
    public function render(HttpUser $user,array $c):string
    {
        $e=[PilotView::class,'e'];$id=$e($c['id']);$order=$c['order'];$date=static fn(mixed $value):string=>'<time datetime="'.$e($value).'">'.PilotView::date($value).'</time>';
        $notice=isset($c['flash'])&&$c['flash']?'<div class="fm2-alert" role="status">'.$e($c['flash']['message']).'</div>':'';
        $stage=$c['opened']?4:($order===null?1:($order['status']==='prepared'?2:3));
        $steps=[['Распоряжение',$order===null?'Требуется':'Сформировано'],['Номер 1С ДО',$order!==null&&$order['status']==='registered'?'Внесён':'Ожидается'],['Открытие работ',$c['opened']?'Открыты':'Не открыты'],['Монтаж',$c['opened']?'Доступен':'Недоступен']];
        $process='<div class="fm2-process" aria-label="Этапы процесса">';foreach($steps as$i=>$step){$state=$i+1<$stage?' fm2-process-step--done':($i+1===$stage?' fm2-process-step--current':'');$process.='<div class="fm2-process-step'.$state.'"><strong>'.$step[0].'</strong><span>'.$step[1].'</span></div>';}$process.='</div>';

        [$command,$downloads]=$this->command($c,$id,$order);
        $overview='<div class="fm2-section-grid">'.$this->panel('Положение в процессе',PilotView::dl([['Состояние',$e($c['status'])],['Распоряжение',$order===null?'Не сформировано':($order['registrationNumber']===null?'Ожидает регистрации':'№ '.$e($order['registrationNumber']))],['Открытие работ',$c['opened']?'Открыты '.$date($c['actualStartDate']):'Ожидается']])).$this->panel('Контрольные даты',PilotView::dl([['Плановое начало',$date($c['plannedStartDate'])],['Плановое окончание',$date($c['plannedFinishDate'])],['Фактическое начало',$c['actualStartDate']?$date($c['actualStartDate']):'—']])).'</div>';
        $data='<div class="fm2-section-grid">'.$this->panel('Идентификация и адрес',PilotView::dl([['Объект монтажа','№ '.$id],['Регистрационный номер',$e($c['registrationNumber'])],['Адрес',$e($c['address'])],['Подъезд',$e($c['entrance'])]])).$this->panel('Плановый период',PilotView::dl([['Начало',$date($c['plannedStartDate'])],['Окончание',$date($c['plannedFinishDate'])],['Источник','Данные объекта монтажа']])).'</div>';
        $works=$this->panel('Монтажные работы',PilotView::dl($c['opened']?[['Состояние','Работы открыты'],['Фактическое начало',PilotView::date($c['actualStartDate'])],['Открыл',$e($c['openedByName']??$c['openedByUserId'])],['Чек-лист','Доступен']]:[['Состояние','Работы ещё не открыты'],['Условие','Зарегистрированное распоряжение']]));
        $docs=$this->panel('Распоряжение о закреплении',$order===null?'<p>Документ ещё не сформирован.</p>':PilotView::dl([['Дата',PilotView::date($order['orderDate'])],['Версия',$e($order['version'])],['Номер 1С ДО',$e($order['registrationNumber']??'Не внесён')]]).$downloads);
        $engineer=$c['controlEngineer']??null;$engineerValue=$engineer===null?'Не назначен':$e($engineer['fullName']).' · '.$e($engineer['position']);$engineerForm='';if($c['canAssignEngineer']??false){$options='<option value="">Выберите пользователя</option>';foreach($c['engineers']as$x)$options.='<option value="'.$e($x['userId']).'"'.(($engineer['userId']??null)===$x['userId']?' selected':'').'>'.$e($x['fullName']).'</option>';$engineerForm='<form class="fm2-engineer-form" method="post" action="/pilot/objects/'.$id.'/control-engineer"><input type="hidden" name="csrfToken" value="'.$e($c['csrfToken']).'"><input type="hidden" name="processRevision" value="'.$e($c['processRevision']).'"><label class="shlz-field shlz-field--select"><span class="shlz-field__label">Инженер строительного контроля</span><span class="shlz-field__control"><select class="shlz-select" name="controlEngineerUserId" required>'.$options.'</select></span></label><button class="shlz-button" type="submit">Назначить</button><small>Доступны активные пользователи с ролью «Строительный контроль».</small></form>';}$teamRows=[['Инженер стройконтроля',$engineerValue]];if($order===null)$teamRows[]=['Монтажники','Ещё не назначены'];else foreach($order['installers']as$x)$teamRows[]=['Монтажник',$e($x['fullName']).' · таб. '.$e($x['tabId']).' · '.$e($x['position'])];$team=$this->panel('Команда объекта',PilotView::dl($teamRows).$engineerForm);
        $history='<div class="fm2-event-list">';if($c['events']===[])$history.='<p>Событий пока нет.</p>';else foreach($c['events']as$x)$history.='<div class="fm2-event"><time>'.$e($x['occurredAt']).'</time><div><strong>'.$e($x['label']??$x['type']).'</strong><br><small>Пользователь '.$e($x['actorId']).'</small></div></div>';$history.='</div>';$history=$this->panel('История объекта',$history);
        $tabs=['Обзор'=>$overview,'Данные объекта'=>$data,'Работы'=>$works,'Документы'=>$docs,'Команда'=>$team,'История'=>$history];$inputs=$labels=$panels='';$n=0;foreach($tabs as$label=>$panel){$n++;$inputs.='<input type="radio" name="object-tab" id="object-tab-'.$n.'"'.($n===1?' checked':'').'>';$labels.='<label for="object-tab-'.$n.'">'.$label.'</label>';$panels.='<section class="fm2-tab-panel" role="tabpanel">'.$panel.'</section>';}
        $body='<div class="fm2-object-head"><div><div class="fm2-page-header"><h1>Объект монтажа № '.$id.'</h1></div><div class="fm2-object-meta"><span>'.$e($c['registrationNumber']).'</span><span>·</span><span>'.$e($c['address']).'</span><span>· подъезд '.$e($c['entrance']).'</span></div></div><span class="shlz-status">'.$e($c['status']).'</span></div>'.$notice.$process.'<section class="fm2-command">'.$command.'</section><div class="fm2-tabs">'.$inputs.'<div class="fm2-tab-list" role="tablist">'.$labels.'</div><div class="fm2-tab-panels">'.$panels.'</div></div>';
        $field=$c['flash']['field']??null;if(\in_array($field,['registrationNumber','actualStartDate'],true)){$errorId=$field.'-error';$body=\str_replace('role="status"','role="status" id="'.$errorId.'"',$body);$body=\str_replace('name="'.$field.'"','name="'.$field.'" aria-invalid="true" aria-describedby="'.$errorId.'"',$body);}
        return PilotView::document($user,'Объект монтажа № '.$id,'Объекты монтажа',PilotView::breadcrumb([['Объекты монтажа','/pilot/objects']],'Объект монтажа № '.$id),$body);
    }

    private function command(array $c,string $id,?array $order):array
    {
        $e=[PilotView::class,'e'];$downloads='';
        if($order===null)return ['<div><h2>Сформируйте распоряжение</h2><p>'.(($c['controlEngineer']??null)===null?'Сначала назначьте инженера в карточке объекта, затем выберите монтажников.':'Инженер подтянется из карточки объекта, в распоряжении выберите монтажников.').'</p></div>'.((($c['canPrepare']??false)&&!($c['hasPtoAct']??false)&&($c['controlEngineer']??null)!==null)?'<a class="fm2-primary-link" href="/pilot/objects/'.$id.'/assignment-order/prepare">Сформировать распоряжение</a>':''),''];
        $base='/pilot/objects/'.$id.'/assignment-orders/'.$e($order['version']);$downloads='<div class="fm2-actions"><span class="shlz-tag">Версия '.$e($order['version']).'</span><a class="shlz-link" href="'.$base.'/artifacts/order">Скачать распоряжение</a><a class="shlz-link" href="'.$base.'/artifacts/appendix">Скачать приложение</a></div>';
        if(!$c['opened']&&$order['status']==='prepared'&&($c['canRegister']??false)){$form='<form class="fm2-inline-form" method="post" action="'.$base.'/registration">'.$this->hidden($c,$order).'<label for="registrationNumber">Номер распоряжения в 1С ДО</label><input id="registrationNumber" name="registrationNumber" maxlength="120" required><button class="shlz-button" type="submit">Сохранить номер</button></form>';return ['<div><h2>Внесите номер 1С ДО</h2><p>Документы сформированы и доступны для скачивания.</p></div>'.$form,$downloads];}
        if(!$c['opened']&&$order['status']==='registered'&&($c['canOpen']??false)){$form='<form class="fm2-inline-form" method="post" action="/pilot/objects/'.$id.'/open">'.$this->hidden($c,$order).'<label for="actualStartDate">Фактическая дата начала работ</label><input id="actualStartDate" type="date" name="actualStartDate" required><small>Не раньше даты распоряжения и не позже сегодняшней даты</small><button class="shlz-button" type="submit">Открыть работы</button></form>';return ['<div><h2>Откройте монтажные работы</h2><p>Распоряжение зарегистрировано.</p></div>'.$form,$downloads];}
        return ['<div><h2>Работы открыты</h2><p>Следующий шаг — первая инспекция строительного контроля.</p></div><span class="shlz-status">Ответственный: '.$e($c['controlEngineer']['fullName']??'не назначен').'</span>',$downloads];
    }
    private function hidden(array $c,array $order):string{$e=[PilotView::class,'e'];return '<input type="hidden" name="csrfToken" value="'.$e($c['csrfToken']).'"><input type="hidden" name="processRevision" value="'.$e($c['processRevision']).'"><input type="hidden" name="assignmentOrderVersion" value="'.$e($order['version']).'">';}
    private function panel(string $title,string $content):string{return '<section class="fm2-panel"><h2>'.$title.'</h2>'.$content.'</section>';}
    public function renderCompatibility(HttpUser $user,array $c):string{return $this->render($user,$c);}
}
